import{_ as r,o,c as a,a5 as l}from"./chunks/framework.Bt0SrEfo.js";const b=JSON.parse('{"title":"浏览器原理:推荐深入","description":"","frontmatter":{},"headers":[],"relativePath":"browser/15-further-reading.md","filePath":"browser/15-further-reading.md","lastUpdated":1790007753000}'),t={name:"browser/15-further-reading.md"};function i(n,e,s,h,g,c){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="浏览器原理-推荐深入" tabindex="-1">浏览器原理:推荐深入 <a class="header-anchor" href="#浏览器原理-推荐深入" aria-label="Permalink to &quot;浏览器原理:推荐深入&quot;">​</a></h1><h2 id="经典书籍" tabindex="-1">经典书籍 <a class="header-anchor" href="#经典书籍" aria-label="Permalink to &quot;经典书籍&quot;">​</a></h2><ul><li><p><strong>《How Browsers Work: Behind the scenes of modern web browsers》</strong> —— Tali Garsiel &amp; Paul Irish。<strong>最权威的浏览器原理入门</strong>(基于 Chrome/Safari/Firefox)。免费在线版本,有完整中文翻译。强烈建议通读。</p></li><li><p><strong>《WebKit 技术内幕》</strong> —— 朱永盛。WebKit 内核架构深度讲解(适合 Safari/iOS 工程师)。基于 WebKit 源码剖析渲染、JS、布局、动画。</p></li><li><p><strong>《浏览器工作原理与实践》</strong> —— 李兵(极客时间)。从工程师视角讲解浏览器原理,实战案例丰富,涵盖性能优化、安全、网络。</p></li><li><p><strong>《Web 性能权威指南》(High Performance Browser Networking)</strong> —— Ilya Grigorik。Google 性能团队出品,网络层(HTTP/HTTPS/缓存)圣经。</p></li><li><p><strong>《High Performance Websites》</strong> —— Steve Souders。&quot;14 条性能规则&quot;开山之作。</p></li></ul><h2 id="google-官方资源" tabindex="-1">Google 官方资源 <a class="header-anchor" href="#google-官方资源" aria-label="Permalink to &quot;Google 官方资源&quot;">​</a></h2><h3 id="chrome-团队博客" tabindex="-1">Chrome 团队博客 <a class="header-anchor" href="#chrome-团队博客" aria-label="Permalink to &quot;Chrome 团队博客&quot;">​</a></h3><ul><li><p><strong><a href="https://developer.chrome.com/blog/inside-browser-part1" target="_blank" rel="noreferrer">Inside look at modern web browser</a></strong>(Mariko Kosaka 4-part 系列)</p><ul><li>Part 1: 多进程架构</li><li>Part 2: 导航流程</li><li>Part 3: 渲染进程内部</li><li>Part 4: 合成器线程</li></ul></li><li><p><strong><a href="https://chromium.googlesource.com/chromium/src/+/main/docs/" target="_blank" rel="noreferrer">Inside Chromium</a></strong> —— 源码级文档</p></li><li><p><strong><a href="https://docs.google.com/document/d/1aitpCOCX-zJJ-Z9mAggPn0GoaVA4nUexZj_3_CeHIK8" target="_blank" rel="noreferrer">Blink Dev</a></strong> —— Blink 渲染引擎设计</p></li></ul><h3 id="web-dev-系列" tabindex="-1">web.dev 系列 <a class="header-anchor" href="#web-dev-系列" aria-label="Permalink to &quot;web.dev 系列&quot;">​</a></h3><ul><li><strong><a href="https://web.dev/performance/" target="_blank" rel="noreferrer">web.dev/performance</a></strong> —— 性能优化体系</li><li><strong><a href="https://web.dev/learn/performance/" target="_blank" rel="noreferrer">web.dev/learn/performance</a></strong> —— 学习路径</li><li><strong><a href="https://web.dev/vitals/" target="_blank" rel="noreferrer">web.dev/vitals</a></strong> —— Core Web Vitals 详解</li><li><strong><a href="https://web.dev/measure/" target="_blank" rel="noreferrer">web.dev/measure</a></strong> —— 度量方法</li><li><strong><a href="https://web.dev/howbrowserswork/" target="_blank" rel="noreferrer">How Browsers Work</a></strong> —— 浏览器工作原理</li></ul><h2 id="规范与标准" tabindex="-1">规范与标准 <a class="header-anchor" href="#规范与标准" aria-label="Permalink to &quot;规范与标准&quot;">​</a></h2><ul><li><strong><a href="https://html.spec.whatwg.org/" target="_blank" rel="noreferrer">HTML Living Standard</a></strong> —— HTML 规范权威</li><li><strong><a href="https://www.w3.org/Style/CSS/" target="_blank" rel="noreferrer">CSS Working Group</a></strong> —— CSS 规范</li><li><strong><a href="https://tc39.es/" target="_blank" rel="noreferrer">ECMAScript</a></strong> —— JS 规范</li><li><strong><a href="https://fetch.spec.whatwg.org/" target="_blank" rel="noreferrer">WHATWG Fetch</a></strong> —— Fetch API 规范</li><li><strong><a href="https://w3c.github.io/ServiceWorker/" target="_blank" rel="noreferrer">Service Worker Spec</a></strong> —— Service Worker 规范</li></ul><h2 id="chrome-devtools-文档" tabindex="-1">Chrome DevTools 文档 <a class="header-anchor" href="#chrome-devtools-文档" aria-label="Permalink to &quot;Chrome DevTools 文档&quot;">​</a></h2><ul><li><strong><a href="https://developer.chrome.com/docs/devtools/performance/" target="_blank" rel="noreferrer">Performance 面板</a></strong> —— 火焰图、长任务、性能分析</li><li><strong><a href="https://developer.chrome.com/docs/devtools/memory-problems/" target="_blank" rel="noreferrer">Memory 面板</a></strong> —— 内存泄漏检测</li><li><strong><a href="https://developer.chrome.com/docs/devtools/network/" target="_blank" rel="noreferrer">Network 面板</a></strong> —— 网络瀑布、缓存分析</li><li><strong><a href="https://developer.chrome.com/docs/devtools/coverage/" target="_blank" rel="noreferrer">Coverage 面板</a></strong> —— 找出未使用的 JS/CSS</li></ul><h2 id="源码阅读" tabindex="-1">源码阅读 <a class="header-anchor" href="#源码阅读" aria-label="Permalink to &quot;源码阅读&quot;">​</a></h2><h3 id="chromium" tabindex="-1">Chromium <a class="header-anchor" href="#chromium" aria-label="Permalink to &quot;Chromium&quot;">​</a></h3><ul><li>仓库:<a href="https://chromium.googlesource.com/" target="_blank" rel="noreferrer">chromium.googlesource.com</a></li><li>文档:<a href="https://chromium.googlesource.com/chromium/src/+/main/docs/" target="_blank" rel="noreferrer">chromium/src/docs</a></li><li>关键模块: <ul><li><code>content/renderer/</code> —— 渲染进程</li><li><code>third_party/blink/</code> —— Blink 引擎</li><li><code>v8/</code> —— V8 JS 引擎</li></ul></li></ul><h3 id="v8" tabindex="-1">V8 <a class="header-anchor" href="#v8" aria-label="Permalink to &quot;V8&quot;">​</a></h3><ul><li>仓库:<a href="https://v8.googlesource.com/v8" target="_blank" rel="noreferrer">v8.googlesource.com</a></li><li>博客:<a href="https://v8.dev/blog" target="_blank" rel="noreferrer">v8.dev/blog</a></li><li>文档:<a href="https://v8.dev/docs" target="_blank" rel="noreferrer">v8.dev/docs</a></li></ul><h3 id="webkit" tabindex="-1">WebKit <a class="header-anchor" href="#webkit" aria-label="Permalink to &quot;WebKit&quot;">​</a></h3><ul><li>仓库:<a href="https://github.com/WebKit/WebKit" target="_blank" rel="noreferrer">github.com/WebKit/WebKit</a></li><li>博客:<a href="https://webkit.org/blog/" target="_blank" rel="noreferrer">webkit.org/blog</a></li></ul><h3 id="gecko-firefox" tabindex="-1">Gecko(Firefox) <a class="header-anchor" href="#gecko-firefox" aria-label="Permalink to &quot;Gecko(Firefox)&quot;">​</a></h3><ul><li>仓库:<a href="https://github.com/mozilla/gecko-dev" target="_blank" rel="noreferrer">github.com/mozilla/gecko-dev</a></li><li>文档:<a href="https://firefox-source-docs.mozilla.org/" target="_blank" rel="noreferrer">firefox-source-docs.mozilla.org</a></li></ul><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><ul><li><strong><a href="https://developer.chrome.com/docs/lighthouse/" target="_blank" rel="noreferrer">Lighthouse</a></strong> —— 综合性能评分</li><li><strong><a href="https://www.webpagetest.org/" target="_blank" rel="noreferrer">WebPageTest</a></strong> —— 多地点多浏览器测试</li><li><strong><a href="https://developer.chrome.com/docs/crux/" target="_blank" rel="noreferrer">Chrome UX Report</a></strong> —— 真实用户性能数据</li><li><strong><a href="https://bundlephobia.com/" target="_blank" rel="noreferrer">bundlephobia</a></strong> —— npm 包体积分析</li></ul><h2 id="视频-演讲" tabindex="-1">视频 / 演讲 <a class="header-anchor" href="#视频-演讲" aria-label="Permalink to &quot;视频 / 演讲&quot;">​</a></h2><ul><li><strong><a href="https://www.youtube.com/@GoogleChromeDevelopers" target="_blank" rel="noreferrer">Google Chrome Developers YouTube</a></strong> —— 大量浏览器原理、性能视频</li><li><strong><a href="https://www.youtube.com/results?search_query=blinkon" target="_blank" rel="noreferrer">BlinkOn</a></strong> —— Blink 引擎会议</li><li><strong>performance.now()</strong> —— 性能专题会议</li><li><strong>JSConf</strong> —— JS 引擎原理、性能演讲</li></ul><h2 id="实战项目-动手学" tabindex="-1">实战项目(动手学) <a class="header-anchor" href="#实战项目-动手学" aria-label="Permalink to &quot;实战项目(动手学)&quot;">​</a></h2><ul><li><strong><a href="https://bugs.chromium.org/" target="_blank" rel="noreferrer">Chromium Bug Tracker</a></strong> —— 看真实问题如何修复</li><li><strong><a href="https://bugzilla.mozilla.org/" target="_blank" rel="noreferrer">Mozilla Bugzilla</a></strong> —— Gecko 引擎问题</li></ul><h2 id="推荐路径" tabindex="-1">推荐路径 <a class="header-anchor" href="#推荐路径" aria-label="Permalink to &quot;推荐路径&quot;">​</a></h2><h3 id="入门-1-2-周" tabindex="-1">入门(1~2 周) <a class="header-anchor" href="#入门-1-2-周" aria-label="Permalink to &quot;入门(1~2 周)&quot;">​</a></h3><ol><li><strong><a href="https://developer.chrome.com/blog/inside-browser-part1" target="_blank" rel="noreferrer">Inside look at modern web browser</a></strong> 4 篇</li><li>《How Browsers Work》对应章节</li><li>web.dev/performance 入门</li></ol><h3 id="进阶-1-2-月" tabindex="-1">进阶(1~2 月) <a class="header-anchor" href="#进阶-1-2-月" aria-label="Permalink to &quot;进阶(1~2 月)&quot;">​</a></h3><ol><li>《WebKit 技术内幕》或《浏览器工作原理与实践》</li><li>web.dev/learn/performance 全套</li><li>Chrome DevTools Performance 面板实战</li></ol><h3 id="高级-2-3-月" tabindex="-1">高级(2~3 月+) <a class="header-anchor" href="#高级-2-3-月" aria-label="Permalink to &quot;高级(2~3 月+)&quot;">​</a></h3><ol><li>读 Chromium 源码(<code>content/renderer/</code>)</li><li>读 V8 源码(TurboFan 编译器)</li><li>跟踪 Chromium 邮件列表 / GitHub Issue</li></ol><h2 id="关键问题清单-面试常考" tabindex="-1">关键问题清单(面试常考) <a class="header-anchor" href="#关键问题清单-面试常考" aria-label="Permalink to &quot;关键问题清单(面试常考)&quot;">​</a></h2><ul><li>从输入 URL 到页面渲染,经历了哪些阶段?</li><li>浏览器为什么多进程?每个进程内有哪些线程?</li><li>JS 单线程,异步怎么实现的?(事件循环)</li><li>微任务 vs 宏任务区别?</li><li>DOM 是怎么构建的?渲染树是什么?</li><li>Layout / Paint / Composite 分别在哪个线程?</li><li>reflow vs repaint 区别?</li><li>transform 为什么性能好?</li><li>浏览器怎么管理缓存?</li></ul><p>读完推荐资料,这些问题都能答上来。</p>',37)])])}const m=r(t,[["render",i]]);export{b as __pageData,m as default};
